import sys

def main():
    N = int(sys.argv[1])

    if N < 2:
        return

    # Sieve of Eratosthenes
    is_prime = [True] * (N + 1)
    is_prime[0] = False
    is_prime[1] = False

    for i in range(2, int(N ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, N + 1, i):
                is_prime[j] = False

    for i in range(2, N + 1):
        if is_prime[i]:
            print(i)

