import sys
import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.isqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def main():
    N = int(sys.argv[1])
    for num in range(2, N + 1):
        if is_prime(num):
            print(num)

