package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
	"unicode"
)

func main() {
	data, err := os.ReadFile("input/text.txt")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}

	text := string(data)
	counts := make(map[string]int)

	// Split into words by non-letter characters, keep only letters
	words := strings.FieldsFunc(text, func(r rune) bool {
		return !unicode.IsLetter(r)
	})

	for _, w := range words {
		lower := strings.ToLower(w)
		if lower != "" {
			counts[lower]++
		}
	}

	// Build slice of word-count pairs
	type pair struct {
		word string
		count int
	}
	pairs := make([]pair, 0, len(counts))
	for w, c := range counts {
		pairs = append(pairs, pair{w, c})
	}

	// Sort: by count descending, then alphabetically ascending
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].count != pairs[j].count {
			return pairs[i].count > pairs[j].count
		}
		return pairs[i].word < pairs[j].word
	})

	// Output
	for _, p := range pairs {
		fmt.Printf("%s: %d\n", p.word, p.count)
	}
}
```

This program:
1. Reads `input/text.txt`
2. Splits the text into tokens using `strings.FieldsFunc`, treating any non-letter character as a delimiter (this handles commas, periods, spaces, newlines, etc.)
3. Converts each word to lowercase
4. Counts frequencies in a map
5. Sorts by count descending, breaking ties alphabetically ascending
6. Prints each `word: count` line to stdout

