package main

import (
	"fmt"
	"math"
)

func calculateDiscount(price float64, quantity int) float64 {
	if quantity < 10 {
		return price * float64(quantity)
	} else if quantity < 50 {
		return price * float64(quantity) * 0.9
	}
	return price * float64(quantity) * 0.75
}

func main() {
	type testCase struct {
		description string
		price       float64
		quantity    int
		expected    float64
	}

	tests := []testCase{
		{"boundary: quantity 9 (no discount)", 10.0, 9, 10.0 * 9},
		{"boundary: quantity 10 (10% discount)", 10.0, 10, 10.0 * 10 * 0.9},
		{"boundary: quantity 49 (10% discount)", 10.0, 49, 10.0 * 49 * 0.9},
		{"boundary: quantity 50 (25% discount)", 10.0, 50, 10.0 * 50 * 0.75},
	}

	for _, tc := range tests {
		got := calculateDiscount(tc.price, tc.quantity)
		if math.Abs(got-tc.expected) < 1e-9 {
			fmt.Printf("PASS: %s\n", tc.description)
		} else {
			fmt.Printf("FAIL: %s (expected: %.2f, got: %.2f)\n", tc.description, tc.expected, got)
		}
	}
}
```

This program:

1. **Copies the `calculateDiscount` function** directly into the file (no external imports).
2. **Defines 4 test cases** covering all boundary conditions:
   - `quantity = 9` → no discount (just `price * quantity`)
   - `quantity = 10` → 10% discount (the first threshold where the 0.9 multiplier kicks in)
   - `quantity = 49` → still 10% discount (just below the 0.75 threshold)
   - `quantity = 50` → 25% discount (the 0.75 multiplier applies)
3. **Uses `math.Abs` with a small epsilon (1e-9)** to compare floating-point results, avoiding false failures due to floating-point representation.
4. **Prints `PASS` or `FAIL`** with the expected/got values on failure, exactly as specified.

Running this program will output:
```
PASS: boundary: quantity 9 (no discount)
PASS: boundary: quantity 10 (10% discount)
PASS: boundary: quantity 49 (10% discount)
PASS: boundary: quantity 50 (25% discount)
```

