package main

import (
	"fmt"
	"os"
	"strconv"
)

func sieve(n int) []int {
	if n < 2 {
		return nil
	}

	isPrime := make([]bool, n+1)
	for i := 2; i <= n; i++ {
		isPrime[i] = true
	}

	for i := 2; i*i <= n; i++ {
		if isPrime[i] {
			for j := i * i; j <= n; j += i {
				isPrime[j] = false
			}
		}
	}

	var primes []int
	for i := 2; i <= n; i++ {
		if isPrime[i] {
			primes = append(primes, i)
		}
	}
	return primes
}

func main() {
	if len(os.Args) < 2 {
		os.Exit(1)
	}

	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		os.Exit(1)
	}

	primes := sieve(n)
	for _, p := range primes {
		fmt.Println(p)
	}
}
```

This program:

1. **Reads the integer N** from the first command-line argument using `os.Args[1]`.
2. **Uses the Sieve of Eratosthenes** to efficiently find all primes up to N. It marks composite numbers as non-prime starting from each prime's square, then collects all remaining marked-as-prime numbers.
3. **Prints each prime on its own line** using `fmt.Println`. If N < 2, the slice is nil and nothing is printed.

Example usage:
```
$ go run main.go 20
2
3
5
7
11
13
17
19
```

```
$ go run main.go 1
(no output)
```

